model_output:
public void Save()
{
    byte[] outArray;
    string text = ToText();
    if (utf8Bom)
    {
        using (var bos = new MemoryStream())
        {
            bos.WriteByte(0xEF);
            bos.WriteByte(0xBB);
            bos.WriteByte(0xBF);
            bos.Write(Encoding.UTF8.GetBytes(text), 0, text.Length);
            outArray = bos.ToArray();
        }
    }
    else
    {
        outArray = Constants.Encode(text);
    }
    using (var lf = new LockFile(GetFile()))
    {
        if (!lf.Lock())
            throw new LockFailedException(GetFile());
        try
        {
            lf.SetNeedSnapshot(true);
            lf.Write(outArray);
            if (!lf.Commit())
                throw new IOException(string.Format(JGitText.Get().CannotCommitWriteTo, GetFile()));
        }
        finally
        {
            lf.Unlock();
        }
        snapshot = lf.GetCommitSnapshot();
        hash = Hash(outArray);
        FireConfigChangedEvent();
    }
}

