public void VisitContainedRecords(RecordVisitor rv)
{
    PositionTrackingVisitor stv = new PositionTrackingVisitor(rv, 0);
    int blockCount = GetRowBlockCount();
    for (int blockIndex = 0; blockIndex < blockCount; blockIndex++)
    {
        int pos = 0;
        int rowBlockSize = VisitRowRecordsForBlock(blockIndex, rv);
        pos += rowBlockSize;
        int startRowNumber = GetStartRowNumberForBlock(blockIndex);
        int endRowNumber = GetEndRowNumberForBlock(blockIndex);
        List<short> cellOffsets = new List<short>();
        int cellRefOffset = (rowBlockSize - RowRecord.EncodedSize);
        for (int row = startRowNumber; row <= endRowNumber; row++)
        {
            if (_valuesAgg.RowHasCells(row))
            {
                stv.SetPosition(0);
                _valuesAgg.VisitCellsForRow(row, stv);
                int rowCellSize = stv.GetPosition();
                pos += rowCellSize;
                cellOffsets.Add((short)cellRefOffset);
                cellRefOffset = rowCellSize;
            }
        }
        rv.VisitRecord(new DBCellRecord(pos, cellOffsets.ToArray()));
    }
    _unknownRecords.ForEach(rv.VisitRecord);
}

