public void Save() throws IOException 
{
    byte[] outBytes;
    string text = ToText();
    if (Utf8Bom) 
    {
        using (var bos = new MemoryStream()) 
        {
            bos.Write(new byte[] { 0xEF, 0xBB, 0xBF }, 0, 3);
            var textBytes = Encoding.UTF8.GetBytes(text);
            bos.Write(textBytes, 0, textBytes.Length);
            outBytes = bos.ToArray();
        }
    } 
    else 
    {
        outBytes = Constants.Encode(text);
    }

    using (var lf = new LockFile(GetFile())) 
    {
        if (!lf.Lock()) 
        {
            throw new LockFailedException(GetFile());
        }

        try 
        {
            lf.NeedSnapshot = true;
            lf.Write(outBytes);
            if (!lf.Commit()) 
            {
                throw new IOException(string.Format(JGitText.Instance.CannotCommitWriteTo, GetFile()));
            }
        } 
        finally 
        {
            lf.Unlock();
        }
    }

    snapshot = lf.CommitSnapshot;
    hash = Hash(outBytes);
    FireConfigChangedEvent();
}

