public void Save()
{
    byte[] outBytes;
    string text = ToText();
    if (utf8Bom)
    {
        using (var ms = new MemoryStream())
        {
            ms.WriteByte(0xEF);
            ms.WriteByte(0xBB);
            ms.WriteByte(0xBF);
            var textBytes = Encoding.UTF8.GetBytes(text);
            ms.Write(textBytes, 0, textBytes.Length);
            outBytes = ms.ToArray();
        }
    }
    else
    {
        outBytes = Constants.Encode(text);
    }

    using (var lf = new LockFile(GetFile()))
    {
        if (!lf.Lock())
        {
            throw new LockFailedException(GetFile());
        }

        try
        {
            lf.SetNeedSnapshot(true);
            lf.Write(outBytes);
            if (!lf.Commit())
            {
                throw new IOException(string.Format("Cannot commit write to {0}", GetFile()));
            }
        }
        finally
        {
            lf.Unlock();
        }

        snapshot = lf.GetCommitSnapshot();
        hash = Hash(outBytes);
        FireConfigChangedEvent();
    }
}

