public void Save()
{
    byte[] outArray;
    string text = ToText();
    if (utf8Bom)
    {
        var bos = new MemoryStream();
        bos.WriteByte(0xEF);
        bos.WriteByte(0xBB);
        bos.WriteByte(0xBF);
        byte[] textBytes = Encoding.UTF8.GetBytes(text);
        bos.Write(textBytes, 0, textBytes.Length);
        outArray = bos.ToArray();
    }
    else
    {
        outArray = Constants.Encode(text);
    }

    var lf = new LockFile(GetFile());
    if (!lf.Lock())
        throw new LockFailedException(GetFile());

    try
    {
        lf.SetNeedSnapshot(true);
        lf.Write(outArray);
        if (!lf.Commit())
            throw new IOException(string.Format(JGitText.Get().cannotCommitWriteTo, GetFile()));
    }
    finally
    {
        lf.Unlock();
    }

    snapshot = lf.GetCommitSnapshot();
    hash = Hash(outArray);
    FireConfigChangedEvent();
}

